{
  "findings": [
    {
      "check_id": "CKV_GCP_102",
      "title": "Cloud Run service allows unauthenticated public invocation",
      "resource": "google_cloud_run_service_iam_binding.search_service_public",
      "severity": "MEDIUM",
      "explanation": "Granting roles/run.invoker to allUsers allows anyone on the internet to invoke the Cloud Run service without authentication. This can expose the service and its functionality to unauthorized users."
    }
  ],
  "patched_code": "variable "search_service_invoker_members" {
  description = "Authenticated IAM principals permitted to invoke the search Cloud Run service."
  type        = set(string)

  validation {
    condition = (
      length(var.search_service_invoker_members) > 0 &&
      !contains(var.search_service_invoker_members, "allUsers") &&
      !contains(var.search_service_invoker_members, "allAuthenticatedUsers")
    )
    error_message = "Invoker members must contain at least one specific IAM principal and must not include allUsers or allAuthenticatedUsers."
  }
}

resource "google_cloud_run_service_iam_binding" "search_service_public" {
  location = google_cloud_run_service.search_service.location
  project  = google_cloud_run_service.search_service.project
  service  = google_cloud_run_service.search_service.name
  role     = "roles/run.invoker"
  members  = var.search_service_invoker_members
}
",
  "fix_summary": "Replaced the public allUsers grant with a required set of explicitly supplied IAM principals. Added validation that prevents both anonymous and broadly authenticated public access."
}
